import java.util.*;class Solution{List<String>o=new ArrayList<>();void f(String s,int p,int part,List<String>v){if(part==4){if(p==s.length())o.add(String.join(".",v));return;}for(int l=1;l<=3&&p+l<=s.length();l++){if(l>1&&s.charAt(p)=='0')break;String x=s.substring(p,p+l);if(Integer.parseInt(x)>255)break;v.add(x);f(s,p+l,part+1,v);v.remove(v.size()-1);}}public List<String> restoreIpAddresses(String s){f(s,0,0,new ArrayList<>());return o;}}
